// E-5: the kinematic flight simulator, a line-by-line port of src/shared/flightsim.ts (web source `sim`). Pure C#: no UnityEngine, so it
// compiles in every platform and the EditMode golden test (contracts/golden/flightsim.json, generated by the web's own code) runs it directly.
//
// WHAT THIS IS: a KINEMATIC model, not PX4 and not a physics engine. The vehicle is a point that follows a commanded velocity with a first-order
// lag; its attitude is derived from the acceleration it needs. It exists so that the flight controls (commands, keyboard, gamepad, click to
// fly) can be tried without PX4 SITL. WHAT IT IS NOT: a model of the X500, a PX4 controller, an aerodynamic or battery model. Every constant
// below is PLAUSIBLE, NONE WAS FITTED to the real vehicle (calibrating them against the real ULog is F-2, a later package), and every value it
// produces is labelled "simulado" in the UI (provenance estimated, origin "Simulador de vuelo"); it is NEVER presented as SITL.
//
// Frames: NED metres for position and velocity (z down), yaw clockwise from north, roll right-wing-down positive, pitch nose-up positive,
// quaternion Hamilton scalar first rotating body FRD into NED: the conventions of TelemetryFrame.

using System;

namespace WebGL.Telemetry
{
    /// <summary>Constants of the model (SIM_LIMITS of the web).</summary>
    public static class SimLimits
    {
        /// <summary>Horizontal speed at full stick and in fly_to / RTL, m/s.</summary>
        public const double MaxSpeed = 6;
        public const double MaxClimb = 2.5;
        public const double MaxDescent = 1.5;
        public const double LandSpeed = 0.8;
        /// <summary>deg/s at full yaw stick.</summary>
        public const double MaxYawRate = 100;
        /// <summary>First-order lag of the velocity response, s.</summary>
        public const double VelocityTau = 0.55;
        public const double MaxAccel = 5;
        /// <summary>Attitude follows the required tilt with this lag, s.</summary>
        public const double TiltTau = 0.14;
        /// <summary>Extra tilt per m/s of speed (drag), 1/s.</summary>
        public const double DragTilt = 0.25;
        public const double MaxTiltDeg = 35;
        /// <summary>Geofence DEFAULTS, m (the live values are in SimState.cfg, editable with FlightSim.SetConfig; these three stay so the golden keeps its limits).</summary>
        public const double Radius = 120;
        public const double Ceiling = 60;
        public const double RtlAltitude = 10;
        public const double OrbitSpeed = 2.5;
        /// <summary>No stick sample for this long while piloting = hold position (dead-man).</summary>
        public const double ManualTimeoutS = 0.6;
        /// <summary>Hover motor command, measured in the real flight (0.62; docs/CALIBRACION_MODELO_FALLAS.md of the web).</summary>
        public const double HoverThrottle = 0.62;
        /// <summary>Battery: 5000 mAh 4S, about 22 A in hover.</summary>
        public const double CapacityAh = 5;
        public const double HoverAmps = 22;
        public const double AvionicsAmps = 0.5;
        public const double MotorKv = 920;
    }

    public enum SimMode { Idle, Takeoff, Hold, Goto, Manual, Land, Rtl, Orbit }

    public enum RtlPhase { Climb, Return, Land }

    /// <summary>Position target of takeoff / hold / goto / rtl: north, east, altitude (up positive).</summary>
    public struct SimTarget
    {
        public double n, e, alt;
    }

    public sealed class SimOrbit
    {
        public double cn, ce, r;
    }

    public struct SimSticks
    {
        public double x, y, z, r;
        public SimSticks(double x, double y, double z, double r) { this.x = x; this.y = y; this.z = z; this.r = r; }
        public static readonly SimSticks Neutral = new SimSticks(0, 0, 500, 0);
    }

    /// <summary>The answer to a command: ok, a Spanish detail like the acks of the bridge, and a line for the event list.</summary>
    public struct SimReply
    {
        public bool ok;
        public string detail;
        public string evt;
    }

    public sealed class SimState
    {
        /// <summary>Seconds since the simulator started.</summary>
        public double t;
        public double[] p = new double[3];
        public double[] v = new double[3];
        public double yaw, roll, pitch, yawRate;
        public bool armed, landed = true;
        public SimMode mode = SimMode.Idle;
        public SimTarget target;
        /// <summary>null = none.</summary>
        public double? yawTarget;
        public SimOrbit orbit;
        public RtlPhase rtlPhase = RtlPhase.Climb;
        /// <summary>The pilot (keyboard / gamepad) asked for the sticks: takeoff ends in manual instead of hold.</summary>
        public bool pilot;
        public SimSticks manual = SimSticks.Neutral;
        /// <summary>Seconds since the last stick sample.</summary>
        public double manualAge = double.PositiveInfinity;
        /// <summary>Battery state of charge 0..1.</summary>
        public double rem = 1;
        public double amps;
        public double[] u = new double[4];
        public double[] tempMotor = new double[4];
        public double tempBattery;
        public double ambientC;
        /// <summary>Local configuration: geofence (radius, ceiling, RTL altitude) and what other tools add.</summary>
        public SimConfig cfg = new SimConfig();
        /// <summary>Gust of each horizontal axis and the state of its random generator (seeded from cfg.wind.seed).</summary>
        public WindState wind;
    }

    public static class FlightSim
    {
        const double G = 9.80665;
        const double Deg = Math.PI / 180;

        /// <summary>Commands the simulator accepts (HelloMessage.commands). motor_off / restore are PX4 fault injection and do not exist here.</summary>
        public static readonly string[] Commands = { "takeoff", "set_altitude", "land", "fly_to", "yaw", "orbit", "rtl", "hold", "pilot", "manual" };

        public const string NotAvailable = "no disponible en el simulador del navegador";

        public static SimState Create(double ambientC = 22, SimConfig cfg = null)
        {
            var s = new SimState { ambientC = ambientC, tempBattery = ambientC, cfg = cfg != null ? cfg.Clone() : new SimConfig() };
            s.wind = new WindState(s.cfg.wind.seed);
            for (int i = 0; i < 4; i++) s.tempMotor[i] = ambientC;
            return s;
        }

        static double Clamp(double v, double lo, double hi) => Math.Min(hi, Math.Max(lo, v));
        static double WrapPi(double a) => Math.Atan2(Math.Sin(a), Math.Cos(a));
        static bool Flying(SimState s) => s.armed && !s.landed;

        /// <summary>JS `Number(x) || fallback`: a missing, NaN or zero value takes the fallback.</summary>
        static double NumOr(double? x, double fallback)
        {
            double v = x ?? double.NaN;
            return double.IsNaN(v) || v == 0 ? fallback : v;
        }

        /// <summary>Hold where the vehicle will have stopped (its position plus the distance the velocity lag still carries it), so it does not come back.</summary>
        static void HoldHere(SimState s, double? altOverride = null)
        {
            double alt = altOverride ?? -s.p[2];
            s.target = new SimTarget { n = s.p[0] + s.v[0] * SimLimits.VelocityTau, e = s.p[1] + s.v[1] * SimLimits.VelocityTau, alt = alt };
            s.yawTarget = null;
            s.orbit = null;
        }

        static SimReply Ok(string evt = null) => new SimReply { ok = true, evt = evt };
        static SimReply No(string detail) => new SimReply { ok = false, detail = detail };
        static bool NeedFlight(SimState s, out SimReply no)
        {
            if (Flying(s)) { no = default; return false; }
            no = No("el dron está en tierra: despega primero");
            return true;
        }

        /// <summary>Applies a command. Mutates `s`.</summary>
        public static SimReply Command(SimState s, CommandMessage msg)
        {
            SimReply no;
            switch (msg.name)
            {
                case "takeoff":
                {
                    if (Flying(s)) return No("ya está en vuelo");
                    double alt = Clamp(NumOr(msg.altitude, 5), 1, s.cfg.ceiling);
                    string evt = "Despegue a " + JsMath.ToFixed(alt, 0) + " m";
                    if (s.rem < 0.2)
                    {
                        s.rem = 1;
                        evt += " · batería nueva";
                    }
                    s.armed = true;
                    s.landed = false;
                    s.mode = SimMode.Takeoff;
                    HoldHere(s, alt);
                    return Ok(evt);
                }
                case "set_altitude":
                {
                    if (NeedFlight(s, out no)) return no;
                    s.target = new SimTarget { n = s.p[0], e = s.p[1], alt = Clamp(NumOr(msg.altitude, 5), 1, s.cfg.ceiling) };
                    s.orbit = null;
                    s.mode = SimMode.Hold;
                    return Ok();
                }
                case "land":
                {
                    if (NeedFlight(s, out no)) return no;
                    HoldHere(s);
                    s.mode = SimMode.Land;
                    s.pilot = false;
                    return Ok("Aterrizando");
                }
                case "fly_to":
                {
                    if (NeedFlight(s, out no)) return no;
                    double north = msg.north ?? double.NaN, east = msg.east ?? double.NaN;
                    double d = Math.Sqrt(north * north + east * east);
                    if (double.IsNaN(d) || double.IsInfinity(d)) return No("punto no válido");
                    double k = d > s.cfg.radius ? s.cfg.radius / d : 1;
                    s.target = new SimTarget { n = north * k, e = east * k, alt = Clamp(NumOr(msg.altitude, -s.p[2]), 1, s.cfg.ceiling) };
                    s.yawTarget = Math.Atan2(s.target.e - s.p[1], s.target.n - s.p[0]);
                    s.orbit = null;
                    s.mode = SimMode.Goto;
                    return Ok();
                }
                case "yaw":
                {
                    if (NeedFlight(s, out no)) return no;
                    double deg = NumOr(msg.degrees, 0);
                    s.yawTarget = WrapPi((s.yawTarget ?? s.yaw) + deg * Deg);
                    if (s.mode == SimMode.Manual || s.mode == SimMode.Orbit)
                    {
                        HoldHere(s);
                        s.yawTarget = WrapPi(s.yaw + deg * Deg);
                        s.mode = SimMode.Hold;
                    }
                    return Ok();
                }
                case "orbit":
                {
                    if (NeedFlight(s, out no)) return no;
                    double r = Clamp(NumOr(msg.radius, 10), 2, 50);
                    s.orbit = new SimOrbit { cn = s.p[0], ce = s.p[1], r = r };
                    s.target = new SimTarget { n = s.p[0], e = s.p[1], alt = -s.p[2] };
                    s.mode = SimMode.Orbit;
                    return Ok("Órbita de " + JsMath.ToFixed(r, 0) + " m");
                }
                case "rtl":
                {
                    if (NeedFlight(s, out no)) return no;
                    s.target = new SimTarget { n = 0, e = 0, alt = Math.Max(-s.p[2], s.cfg.rtlAltitude) };
                    s.orbit = null;
                    s.rtlPhase = RtlPhase.Climb;
                    s.mode = SimMode.Rtl;
                    s.pilot = false;
                    return Ok("Volviendo al punto de despegue");
                }
                case "hold":
                {
                    s.pilot = false;
                    if (Flying(s) && s.mode != SimMode.Land)
                    {
                        HoldHere(s);
                        s.mode = SimMode.Hold;
                    }
                    return Ok();
                }
                case "pilot":
                {
                    s.pilot = true;
                    s.manualAge = 0;
                    s.manual = SimSticks.Neutral;
                    if (Flying(s) && s.mode != SimMode.Takeoff && s.mode != SimMode.Land) s.mode = SimMode.Manual;
                    return Ok("Pilotaje manual (modo Position simulado)");
                }
                default:
                    return No(NotAvailable);
            }
        }

        /// <summary>
        /// Changes the geofence (and later what other tools put in `cfg`). `next` is merged over the current `cfg` and checked with Geofence.Validate: in flight a
        /// radius or ceiling the vehicle would already be outside of is refused with its reason, and nothing changes (never a teleport). Mutates `s` only when ok.
        /// </summary>
        public static ConfigCheck SetConfig(SimState s, SimConfigPatch next)
        {
            SimConfig merged = s.cfg.Clone();
            if (next.radius.HasValue) merged.radius = next.radius.Value;
            if (next.ceiling.HasValue) merged.ceiling = next.ceiling.Value;
            if (next.rtlAltitude.HasValue) merged.rtlAltitude = next.rtlAltitude.Value;
            if (next.wind != null)
            {
                WindPatch w = next.wind;
                if (w.speed.HasValue) merged.wind.speed = w.speed.Value;
                if (w.fromDeg.HasValue) merged.wind.fromDeg = w.fromDeg.Value;
                if (w.gustSigma.HasValue) merged.wind.gustSigma = w.gustSigma.Value;
                if (w.gustTau.HasValue) merged.wind.gustTau = w.gustTau.Value;
                if (w.seed.HasValue) merged.wind.seed = w.seed.Value;
            }
            ConfigCheck check = Geofence.Validate(merged, s.p, s.armed, s.landed);
            if (!check.ok) return check;
            ConfigCheck wind = Wind.Validate(merged.wind);
            if (!wind.ok) return wind;
            // A new seed starts a new sequence of gusts (from calm); the rest of the wind changes without touching the generator.
            if (merged.wind.seed != s.cfg.wind.seed) s.wind = new WindState(merged.wind.seed);
            s.cfg = merged;
            return ConfigCheck.Ok;
        }

        /// <summary>Wind in force on the vehicle, NED m/s: the mean of cfg.wind plus the gust.</summary>
        public static void WindNow(SimState s, out double n, out double e)
        {
            Wind.Mean(s.cfg.wind, out n, out e);
            n += s.wind.gn;
            e += s.wind.ge;
        }

        /// <summary>A stick sample (MANUAL_CONTROL ranges). Mutates `s`.</summary>
        public static void Manual(SimState s, SimSticks m)
        {
            s.manual = new SimSticks(Clamp(m.x, -1000, 1000), Clamp(m.y, -1000, 1000), Clamp(m.z, 0, 1000), Clamp(m.r, -1000, 1000));
            s.manualAge = 0;
            if (s.pilot && Flying(s) && (s.mode == SimMode.Hold || s.mode == SimMode.Goto || s.mode == SimMode.Orbit)) s.mode = SimMode.Manual;
        }

        /// <summary>Advances the simulation by `dtIn` seconds (clamped to 50 ms; call it several times for longer steps). Mutates and returns `s`.</summary>
        public static SimState Step(SimState s, double dtIn)
        {
            double dt = Clamp(dtIn, 0, 0.05);
            if (dt == 0) return s;
            s.t += dt;
            s.manualAge += dt;
            Wind.StepGusts(s.wind, s.cfg.wind, dt); // the gusts live on while landed; they only act in flight
            double alt = -s.p[2];
            double vn = 0, ve = 0, climb = 0, yawRateCmd = 0;

            double Toward(double n, double e, double speed)
            {
                double dn = n - s.p[0], de = e - s.p[1];
                double d = Math.Sqrt(dn * dn + de * de);
                double sp = Math.Min(speed, d * 1.1);
                if (d > 1e-4) { vn = (dn / d) * sp; ve = (de / d) * sp; }
                return d;
            }
            double ClimbTo(double target) => Clamp((target - alt) * 1.3, -SimLimits.MaxDescent, SimLimits.MaxClimb);
            double SteerYaw(double target) => Clamp(WrapPi(target - s.yaw) * 2.5, -SimLimits.MaxYawRate * Deg, SimLimits.MaxYawRate * Deg);

            if (s.mode == SimMode.Manual && s.manualAge > SimLimits.ManualTimeoutS)
            {
                HoldHere(s); // dead-man: the sticks went quiet
                s.mode = SimMode.Hold;
            }

            switch (s.mode)
            {
                case SimMode.Idle:
                    break;
                case SimMode.Takeoff:
                    Toward(s.target.n, s.target.e, 1);
                    climb = ClimbTo(s.target.alt);
                    if (Math.Abs(s.target.alt - alt) < 0.15) s.mode = s.pilot && s.manualAge < SimLimits.ManualTimeoutS ? SimMode.Manual : SimMode.Hold;
                    break;
                case SimMode.Hold:
                    Toward(s.target.n, s.target.e, 2);
                    climb = ClimbTo(s.target.alt);
                    if (s.yawTarget.HasValue) yawRateCmd = SteerYaw(s.yawTarget.Value);
                    break;
                case SimMode.Goto:
                {
                    double d = Toward(s.target.n, s.target.e, SimLimits.MaxSpeed);
                    climb = ClimbTo(s.target.alt);
                    if (s.yawTarget.HasValue) yawRateCmd = SteerYaw(s.yawTarget.Value);
                    if (d < 0.3) { s.mode = SimMode.Hold; s.yawTarget = null; }
                    break;
                }
                case SimMode.Manual:
                {
                    double f = (s.manual.x / 1000) * SimLimits.MaxSpeed, r = (s.manual.y / 1000) * SimLimits.MaxSpeed;
                    vn = f * Math.Cos(s.yaw) - r * Math.Sin(s.yaw);
                    ve = f * Math.Sin(s.yaw) + r * Math.Cos(s.yaw);
                    double z = (s.manual.z - 500) / 500;
                    climb = z >= 0 ? z * SimLimits.MaxClimb : z * SimLimits.MaxDescent;
                    yawRateCmd = (s.manual.r / 1000) * SimLimits.MaxYawRate * Deg;
                    break;
                }
                case SimMode.Orbit:
                {
                    SimOrbit o = s.orbit;
                    double dn = s.p[0] - o.cn, de = s.p[1] - o.ce;
                    double d = Math.Sqrt(dn * dn + de * de);
                    // radial unit vector (outwards); at the centre itself, leave along the heading
                    double rn = d > 0.05 ? dn / d : Math.Cos(s.yaw), re = d > 0.05 ? de / d : Math.Sin(s.yaw);
                    // The lagged velocity cannot turn by itself: command the inward speed that produces the centripetal acceleration v^2 / r.
                    double radial = Clamp((o.r - d) * 0.8 - ((SimLimits.OrbitSpeed * SimLimits.OrbitSpeed) / o.r) * SimLimits.VelocityTau, -2, 2);
                    vn = rn * radial + -re * SimLimits.OrbitSpeed; // tangent = clockwise seen from above
                    ve = re * radial + rn * SimLimits.OrbitSpeed;
                    climb = ClimbTo(s.target.alt);
                    if (d > 0.5) yawRateCmd = SteerYaw(Math.Atan2(-de, -dn)); // nose to the centre
                    break;
                }
                case SimMode.Rtl:
                    if (s.rtlPhase == RtlPhase.Climb)
                    {
                        climb = ClimbTo(s.target.alt);
                        if (Math.Abs(s.target.alt - alt) < 0.3) s.rtlPhase = RtlPhase.Return;
                    }
                    else if (s.rtlPhase == RtlPhase.Return)
                    {
                        double d = Toward(0, 0, SimLimits.MaxSpeed);
                        climb = ClimbTo(s.target.alt);
                        yawRateCmd = d > 2 ? SteerYaw(Math.Atan2(-s.p[1], -s.p[0])) : 0;
                        if (d < 0.4) s.rtlPhase = RtlPhase.Land;
                    }
                    else
                    {
                        Toward(0, 0, 1);
                        climb = -SimLimits.LandSpeed;
                    }
                    break;
                case SimMode.Land:
                    Toward(s.target.n, s.target.e, 1);
                    climb = -SimLimits.LandSpeed;
                    break;
            }

            // Velocity follows the command with a first-order lag and an acceleration limit.
            double Accel(double cmd, double cur) => Clamp((cmd - cur) / SimLimits.VelocityTau, -SimLimits.MaxAccel, SimLimits.MaxAccel);
            double an = 0, ae = 0, ad = 0;
            // Wind (mean plus gust, NED m/s): it pushes the vehicle after the acceleration limit and the vehicle leans against it; it acts only in flight.
            double wn = 0, we = 0;
            if (Flying(s))
            {
                an = Accel(vn, s.v[0]);
                ae = Accel(ve, s.v[1]);
                ad = Accel(-climb, s.v[2]);
                WindNow(s, out wn, out we);
                s.v[0] += (an + Wind.Push * wn) * dt; s.v[1] += (ae + Wind.Push * we) * dt; s.v[2] += ad * dt;
                s.p[0] += s.v[0] * dt; s.p[1] += s.v[1] * dt; s.p[2] = Math.Min(0, s.p[2] + s.v[2] * dt);
                // Geofence: no further out, no higher.
                double d = Math.Sqrt(s.p[0] * s.p[0] + s.p[1] * s.p[1]);
                if (d > s.cfg.radius) { s.p[0] *= s.cfg.radius / d; s.p[1] *= s.cfg.radius / d; }
                if (-s.p[2] > s.cfg.ceiling) { s.p[2] = -s.cfg.ceiling; s.v[2] = Math.Max(0, s.v[2]); }
                s.yawRate += (yawRateCmd - s.yawRate) * Math.Min(1, dt / 0.12);
                s.yaw = WrapPi(s.yaw + s.yawRate * dt);
                // Touchdown.
                if (s.p[2] >= 0 && s.v[2] >= 0 && (s.mode == SimMode.Land || (s.mode == SimMode.Rtl && s.rtlPhase == RtlPhase.Land) || (s.mode == SimMode.Manual && climb < 0)))
                {
                    s.landed = true;
                    s.armed = false;
                    s.mode = SimMode.Idle;
                    s.v[0] = s.v[1] = s.v[2] = 0;
                    s.p[2] = 0;
                    s.yawRate = 0;
                    an = ae = ad = 0;
                    wn = we = 0;
                }
            }

            // Attitude: the tilt that gives the horizontal acceleration (plus drag), in the body frame.
            double fx = an + SimLimits.DragTilt * (s.v[0] - wn), fy = ae + SimLimits.DragTilt * (s.v[1] - we);
            double fwd = fx * Math.Cos(s.yaw) + fy * Math.Sin(s.yaw);
            double right = -fx * Math.Sin(s.yaw) + fy * Math.Cos(s.yaw);
            double maxTilt = SimLimits.MaxTiltDeg * Deg;
            double pitchT = Flying(s) ? Clamp(-Math.Atan2(fwd, G), -maxTilt, maxTilt) : 0;
            double rollT = Flying(s) ? Clamp(Math.Atan2(right, G), -maxTilt, maxTilt) : 0;
            double k2 = Math.Min(1, dt / SimLimits.TiltTau);
            double rollErr = rollT - s.roll, pitchErr = pitchT - s.pitch;
            s.roll += rollErr * k2;
            s.pitch += pitchErr * k2;

            // Motor commands: collective from the thrust the manoeuvre needs, plus a small differential (Quad-X mixer signs).
            if (s.armed)
            {
                double thrust = Hypot(G - ad, Hypot(an - SimLimits.DragTilt * wn, ae - SimLimits.DragTilt * we)) / G / Math.Max(0.5, Math.Cos(s.roll) * Math.Cos(s.pitch));
                double bas = s.landed ? 0.12 : SimLimits.HoverThrottle * thrust;
                for (int i = 0; i < 4; i++)
                {
                    RotorGeometry r = MixerRotors[i];
                    s.u[i] = Clamp(bas + 0.5 * rollErr * -Math.Sign(r.py) + 0.5 * pitchErr * Math.Sign(r.px) + 0.04 * (yawRateCmd - s.yawRate) * Math.Sign(r.km), 0, 1);
                }
            }
            else s.u[0] = s.u[1] = s.u[2] = s.u[3] = 0;

            // Battery and temperatures (first-order models with made-up but plausible constants; labelled "estimated").
            double load = 0;
            for (int i = 0; i < 4; i++) load += Math.Pow(s.u[i] / SimLimits.HoverThrottle, 1.5);
            load /= 4;
            s.amps = s.armed ? SimLimits.AvionicsAmps + (SimLimits.HoverAmps - SimLimits.AvionicsAmps) * load : SimLimits.AvionicsAmps;
            s.rem = Clamp(s.rem - (s.amps * dt) / 3600 / SimLimits.CapacityAh, 0, 1);
            for (int i = 0; i < 4; i++)
            {
                double rise = 14 * Math.Pow(s.u[i] / SimLimits.HoverThrottle, 3);
                s.tempMotor[i] += (s.ambientC + rise - s.tempMotor[i]) * Math.Min(1, dt / 45);
            }
            s.tempBattery += (s.ambientC + 9 * Math.Pow(s.amps / SimLimits.HoverAmps, 2) - s.tempBattery) * Math.Min(1, dt / 240);
            return s;
        }

        /// <summary>Math.hypot of two values.</summary>
        static double Hypot(double a, double b) => Math.Sqrt(a * a + b * b);

        /// <summary>The Quad-X geometry of the web model (src/shared/quadx.ts PX4_QUAD_X).</summary>
        static readonly RotorGeometry[] MixerRotors = QuadX.Px4QuadX;

        /// <summary>Hamilton quaternion [w, x, y, z] (FRD to NED) from roll, pitch, yaw in radians.</summary>
        public static double[] EulerToQuat(double roll, double pitch, double yaw)
        {
            double cr = Math.Cos(roll / 2), sr = Math.Sin(roll / 2);
            double cp = Math.Cos(pitch / 2), sp = Math.Sin(pitch / 2);
            double cy = Math.Cos(yaw / 2), sy = Math.Sin(yaw / 2);
            return new[] { cr * cp * cy + sr * sp * sy, sr * cp * cy - cr * sp * sy, cr * sp * cy + sr * cp * sy, cr * cp * sy - sr * sp * cy };
        }

        /// <summary>PX4 nav_state shown for each simulator mode: the nearest PX4 mode, since this is not PX4.</summary>
        public static int NavOf(SimMode m)
        {
            switch (m)
            {
                case SimMode.Idle: return 4;
                case SimMode.Takeoff: return 17;
                case SimMode.Hold: return 4;
                case SimMode.Goto: return 4;
                case SimMode.Manual: return 2;
                case SimMode.Land: return 18;
                case SimMode.Rtl: return 5;
                case SimMode.Orbit: return 21;
                default: return 4;
            }
        }

        static double R3(double x) => JsMath.Round(x * 1000) / 1000;
        static double[] R3(double[] a) { var r = new double[a.Length]; for (int i = 0; i < a.Length; i++) r[i] = R3(a[i]); return r; }

        /// <summary>The wire frame for the current state. `tsMs` is the stream time in ms.</summary>
        public static TelemetryFrame Frame(SimState s, double tsMs)
        {
            const int cells = 4;
            double volts = cells * (3.5 + 0.7 * s.rem) - s.amps * 0.012;
            var rpm = new double[4];
            for (int i = 0; i < 4; i++) rpm[i] = JsMath.Round(SimLimits.MotorKv * volts * s.u[i]);
            double meanU = (s.u[0] + s.u[1] + s.u[2] + s.u[3]) / 4;
            return new TelemetryFrame
            {
                ts = tsMs,
                lt = R3(s.t),
                seg = 0,
                q = R3(EulerToQuat(s.roll, s.pitch, s.yaw)),
                p = R3(s.p),
                v = R3(s.v),
                u = R3(s.u),
                rpm = rpm,
                bat = new BatteryState { v = R3(volts), i = R3(s.amps), rem = R3(s.rem) },
                temp = new[] { R3(s.tempMotor[0]), R3(s.tempMotor[1]), R3(s.tempMotor[2]), R3(s.tempMotor[3]), R3(s.tempBattery), s.ambientC },
                vib = R3(s.armed ? 0.6 + 2.2 * meanU : 0.05),
                armed = s.armed,
                landed = s.landed,
                nav = NavOf(s.mode),
            };
        }
    }
}
